import 'package:app/src/home/presentation/pages/home/home_page.dart';import 'package:app/src/main_index.dart';import '../../../cart/presentation/cart/pages/cart_page.dart';import '../bloc/nav_bar_bloc.dart';class NavigationBarPage extends BaseStatelessWidget {  NavigationBarPage({    Key? key,  }) : super(key: key);  @override  Widget build(BuildContext context) {    List<NavigatorModel> items = [      NavigatorModel(        title: strings.cart,        screen: CartPage(),        icon: AppIcons.carts,      ),      NavigatorModel(        title: strings.home,        screen: HomePage(),        icon: AppIcons.home,      ),    ];    return BlocProvider(      create: (context) => NavBarBloc(),      child: BlocBuilder<NavBarBloc, NavBarState>(        builder: (context, state) {          NavBarBloc bloc = NavBarBloc.get(context);          return Scaffold(            bottomNavigationBar: BottomNavigationBar(              onTap: (index) {                bloc.changeIndex(index);              },              currentIndex: bloc.currentIndex,              type: BottomNavigationBarType.fixed,              showSelectedLabels: true,              selectedLabelStyle: headlineMedium.copyWith(fontSize: 14),              unselectedLabelStyle: bodyMedium.copyWith(fontSize: 14),              elevation: 10,              selectedIconTheme: IconThemeData(                color: AppColors.primaryColor,              ),              selectedItemColor: AppColors.primaryColor,              unselectedItemColor: primaryColorDark,              backgroundColor: scaffoldBackgroundColor,              items: items                  .map((e) => BottomNavigationBarItem(                        icon: AppIcon(                          icon: e.icon,                          size: 20,                          padding: 3.paddingBottom,                        ),                        activeIcon: AppIcon(                          icon: e.icon,                          color: AppColors.primaryColor,                          padding: 3.paddingBottom,                          size: 22,                        ),                        label: e.title,                      ))                  .toList(),            ),            body: items[bloc.currentIndex].screen,          );        },      ),    );  }}class NavigatorModel {  final String title;  final Widget screen;  final String icon;  NavigatorModel({    required this.title,    required this.screen,    required this.icon,  });}